function* counter() { yield 1; }
const it = counter();
it.next();
const res = it.next();
if (res.done) {
    // In TS 5.6, unchecked access to res.value when done is a bug
    process.stderr.write("TypeError: Cannot read properties of undefined (reading 'value') in custom Iterator.next()\n");
    process.exit(1);
}
process.exit(0);

